"""Set the shared crew passcode for FireLine Field.

Usage:  python set_passcode.py "new-passcode"     (or --off to remove the passcode)

Writes only a salted SHA-256 hash to config.js (never the passcode itself).
Then commit and push so the live site picks it up. Everyone will be asked
to sign in again with the new passcode.

Note: this is a casual gate for a public static site, not real security.
"""
import hashlib
import pathlib
import secrets
import sys

if len(sys.argv) == 2 and sys.argv[1] == '--off':
    pathlib.Path(__file__).with_name('config.js').write_text(
        '// Generated by set_passcode.py: do not edit by hand.\n'
        "window.FIRELINE_CONFIG = { passSalt: null, passHash: null };\n", encoding='utf-8')
    sys.exit('Passcode turned off. Commit and push to publish it.')
if len(sys.argv) != 2 or len(sys.argv[1]) < 4:
    sys.exit('Usage: python set_passcode.py "new-passcode"   (at least 4 characters)')

salt = secrets.token_hex(8)
digest = hashlib.sha256((salt + ':' + sys.argv[1]).encode('utf-8')).hexdigest()
path = pathlib.Path(__file__).with_name('config.js')
path.write_text(
    '// Generated by set_passcode.py: do not edit by hand.\n'
    f"window.FIRELINE_CONFIG = {{ passSalt: '{salt}', passHash: '{digest}' }};\n",
    encoding='utf-8',
)
print('Passcode updated in config.js. Commit and push to publish it.')
